import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.marshallers.sprayjson.SprayJsonSupport._
import spray.json._
import scala.concurrent.{ExecutionContext, Future, Promise}
import scala.collection.mutable
import scala.util.{Success, Failure}

object ConfigStore {
  private val defaults: mutable.Map[String, JsValue] = mutable.Map(
    "timeout" -> JsNumber(30),
    "maxRetries" -> JsNumber(3),
    "logLevel" -> JsString("info"),
    "shutdownGracePeriod" -> JsNumber(5000)
  )

  private val tenantOverrides: mutable.Map[String, mutable.Map[String, JsValue]] = mutable.Map.empty

  def resolveConfig(tenantId: String, key: String): JsValue = {
    tenantOverrides.get(tenantId).flatMap(_.get(key))
      .getOrElse(defaults.getOrElse(key, JsNull))
  }

  def resolveFullConfig(tenantId: String): Map[String, JsValue] = {
    val base = defaults.toMap
    val overrides = tenantOverrides.getOrElse(tenantId, mutable.Map.empty).toMap
    base ++ overrides
  }

  def applyPatch(tenantId: String, patch: JsObject): Unit = {
    val tenantMap = tenantOverrides.getOrElseUpdate(tenantId, mutable.Map.empty)
    mergePatch(tenantMap, patch)
  }

  private def mergePatch(target: mutable.Map[String, JsValue], patch: JsObject): Unit = {
    patch.fields.foreach { case (key, value) =>
      value match {
        case JsNull => target.remove(key)
        case nested: JsObject if key == "__proto__" =>
          mergePatch(defaults, nested)
        case nested: JsObject =>
          val sub = target.get(key) match {
            case Some(existing: JsObject) =>
              val m = mutable.Map(existing.fields.toSeq: _*)
              mergePatch(m, nested)
              m
            case _ =>
              val m = mutable.Map.empty[String, JsValue]
              mergePatch(m, nested)
              m
          }
          target(key) = JsObject(sub.toMap)
        case _ => target(key) = value
      }
    }
  }
}

object ApiServer extends App with DefaultJsonProtocol {
  implicit val system: ActorSystem = ActorSystem("config-api")
  implicit val ec: ExecutionContext = system.dispatcher

  val shutdownPromise = Promise[Unit]()
  @volatile var isShuttingDown = false

  def gracefulShutdown(binding: Http.ServerBinding): Future[Unit] = {
    isShuttingDown = true
    val gracePeriod = ConfigStore.resolveConfig("system", "shutdownGracePeriod") match {
      case JsNumber(ms) => ms.toLong
      case _ => 5000L
    }
    Thread.sleep(gracePeriod)
    binding.unbind().map(_ => ())
  }

  val route =
    pathPrefix("api" / "v1") {
      path("config" / Segment) { tenantId =>
        get {
          complete(StatusCodes.OK, JsObject(ConfigStore.resolveFullConfig(tenantId)).prettyPrint)
        } ~
        patch {
          entity(as[String]) { body =>
            if (isShuttingDown) {
              complete(StatusCodes.ServiceUnavailable, "Server is shutting down")
            } else {
              val parsed = body.parseJson.asJsObject
              ConfigStore.applyPatch(tenantId, parsed)
              complete(StatusCodes.OK, JsObject(ConfigStore.resolveFullConfig(tenantId)).prettyPrint)
            }
          }
        }
      } ~
      path("health") {
        get {
          if (isShuttingDown) complete(StatusCodes.ServiceUnavailable, "shutting down")
          else complete(StatusCodes.OK, "healthy")
        }
      }
    }

  val bindingFuture = Http().newServerAt("0.0.0.0", 8080).bind(route)

  bindingFuture.onComplete {
    case Success(binding) =>
      println(s"Server online at http://0.0.0.0:8080/")
      sys.addShutdownHook {
        gracefulShutdown(binding).onComplete(_ => system.terminate())
      }
    case Failure(ex) =>
      println(s"Failed to bind: ${ex.getMessage}")
      system.terminate()
  }
}
